package com.example.demo.adapters.jdbc;

import com.example.demo.domain.Author;
import com.example.demo.repository.AuthorRepository;
import java.util.List;
import java.util.Optional;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Repository;

@Repository
public final class JdbcAuthorRepository implements AuthorRepository {

    private final JdbcClient jdbc;

    public JdbcAuthorRepository(JdbcClient jdbc) {
        this.jdbc = jdbc;
    }

    @Override
    public Optional<Author> findById(long id) {
        return jdbc.sql("select id, email from authors where id = :id")
                .param("id", id)
                .query(Author.class)
                .optional();
    }

    @Override
    public List<Author> findAll() {
        return jdbc.sql("select id, email from authors order by id")
                .query(Author.class)
                .list();
    }

    @Override
    public Author save(Author value) {
        return jdbc.sql("insert into authors (email) values (:email) returning id, email")
                .param("email", value.email())
                .query(Author.class)
                .single();
    }

    @Override
    public boolean deleteById(long id) {
        return jdbc.sql("delete from authors where id = :id")
                .param("id", id)
                .update() > 0;
    }
}
